  const NB = 7;
  const bx = [], by = [], br = [], bh = [], bs = [];
  for (let k = 0; k < NB; k++) { bx.push((fr(k*4+1)*2-1)*SR); by.push((fr(k*4+2)*2-1)*SR); br.push(0.5+fr(k*4+3)*1.4); bh.push(fr(k*4+4)); bs.push(0.3+fr(k*9+5)*0.6); }
  for (let j = 0; j < SW; j++) {
